/**
 * NorskBot Chat Widget v2.0
 * Self-contained, embeddable chat widget
 * Usage: <script src="widget.min.js" data-site="SITE_ID" data-api-url="https://api.example.com"></script>
 * Optional: data-color="#0066cc" data-position="bottom-right"
 */
(function() {
  'use strict';
  if (window.NorskChatbot) return;

  class ChatWidget {
    constructor(opts) {
      this.siteId = opts.siteId;
      this.apiUrl = opts.apiUrl || window.location.origin;
      this.color = opts.color || '#0066cc';
      this.position = opts.position || 'bottom-right';
      this.sessionId = 'session_' + Math.random().toString(36).substr(2, 9);
      this.isOpen = false;
      this.config = {};
      this.els = {};
    }

    async init() {
      try {
        await this.loadConfig();
        this.injectStyles();
        this.createWidget();
        this.bindEvents();
      } catch (e) {
        console.error('NorskBot: Init failed', e);
      }
    }

    async loadConfig() {
      try {
        const r = await fetch(this.apiUrl + '/v1/widget/' + this.siteId);
        if (r.ok) {
          const d = await r.json();
          this.config = d.config || {};
          if (this.config.primary_color && !this._userColor) this.color = this.config.primary_color;
          if (this.config.position && !this._userPosition) this.position = this.config.position;
        }
      } catch (e) {
        console.warn('NorskBot: Config load failed, using defaults');
      }
      // Ensure defaults
      this.config.name = this.config.name || 'Chat';
      this.config.welcome_message = this.config.welcome_message || 'Hei! Hvordan kan jeg hjelpe deg?';
    }

    injectStyles() {
      if (document.getElementById('nb-styles')) return;
      const s = document.createElement('style');
      s.id = 'nb-styles';
      const pos = this.position === 'bottom-left' ? 'left:20px;right:auto;' : 'right:20px;left:auto;';
      const posW = this.position === 'bottom-left' ? 'left:0;right:auto;' : 'right:0;left:auto;';
      s.textContent = `
#nb-root{position:fixed;bottom:20px;${pos}z-index:99999;font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Arial,sans-serif;font-size:14px;line-height:1.5}
#nb-btn{width:56px;height:56px;border-radius:50%;background:${this.color};color:#fff;border:none;cursor:pointer;font-size:28px;display:flex;align-items:center;justify-content:center;box-shadow:0 2px 12px rgba(0,0,0,.2);transition:all .3s}
#nb-btn:hover{transform:scale(1.1);box-shadow:0 4px 16px rgba(0,0,0,.3)}
#nb-btn .nb-close{display:none}
#nb-btn.nb-open .nb-open{display:none}
#nb-btn.nb-open .nb-close{display:inline}
#nb-win{position:absolute;bottom:70px;${posW}width:380px;height:520px;background:#fff;border-radius:12px;box-shadow:0 5px 40px rgba(0,0,0,.16);display:flex;flex-direction:column;overflow:hidden;opacity:0;pointer-events:none;transform:translateY(20px) scale(.95);transition:all .3s ease}
#nb-win.nb-show{opacity:1;pointer-events:auto;transform:translateY(0) scale(1)}
#nb-hdr{background:${this.color};color:#fff;padding:14px 16px;display:flex;justify-content:space-between;align-items:center;flex-shrink:0}
#nb-hdr h3{margin:0;font-size:15px;font-weight:600}
#nb-hdr button{background:none;border:none;color:#fff;font-size:20px;cursor:pointer;padding:0;width:28px;height:28px;display:flex;align-items:center;justify-content:center;opacity:.8;transition:opacity .2s}
#nb-hdr button:hover{opacity:1}
#nb-msgs{flex:1;overflow-y:auto;padding:16px;display:flex;flex-direction:column;gap:12px;background:#f7f8fa}
.nb-msg{display:flex;animation:nbSlide .3s ease}
@keyframes nbSlide{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:translateY(0)}}
.nb-msg-u{justify-content:flex-end}
.nb-msg-a{justify-content:flex-start}
.nb-msg-t{max-width:75%;padding:10px 14px;border-radius:14px;word-wrap:break-word;font-size:14px;line-height:1.45}
.nb-msg-u .nb-msg-t{background:${this.color};color:#fff;border-bottom-right-radius:4px}
.nb-msg-a .nb-msg-t{background:#fff;color:#333;border-bottom-left-radius:4px;box-shadow:0 1px 3px rgba(0,0,0,.1)}
.nb-typing{display:flex;align-items:center;gap:4px;padding:12px 16px;max-width:75%}
.nb-typing span{width:7px;height:7px;border-radius:50%;background:#999;animation:nbDot 1.4s ease-in-out infinite}
.nb-typing span:nth-child(2){animation-delay:.2s}
.nb-typing span:nth-child(3){animation-delay:.4s}
@keyframes nbDot{0%,80%,100%{transform:scale(.4);opacity:.4}40%{transform:scale(1);opacity:1}}
.nb-src{margin-top:6px;font-size:12px;max-width:75%}
.nb-src a{color:${this.color};text-decoration:none;display:block}
.nb-src a:hover{text-decoration:underline}
#nb-input{display:flex;gap:8px;padding:12px;background:#fff;border-top:1px solid #eee;flex-shrink:0}
#nb-input input{flex:1;border:1px solid #ddd;border-radius:8px;padding:10px 12px;font-size:14px;font-family:inherit;outline:none;transition:border-color .2s}
#nb-input input:focus{border-color:${this.color}}
#nb-input button{background:${this.color};color:#fff;border:none;border-radius:8px;padding:10px 18px;cursor:pointer;font-weight:500;font-size:14px;transition:opacity .2s}
#nb-input button:hover:not(:disabled){opacity:.85}
#nb-input button:disabled{opacity:.5;cursor:not-allowed}
#nb-pwr{text-align:center;padding:4px;font-size:11px;color:#aaa;background:#fff}
#nb-pwr a{color:#999;text-decoration:none}
#nb-pwr a:hover{color:#666}
@media(max-width:480px){#nb-win{width:calc(100vw - 24px);height:70vh;bottom:68px;${posW.includes('left')?'left:12px':'right:12px'}}}
`;
      document.head.appendChild(s);
    }

    createWidget() {
      const root = document.createElement('div');
      root.id = 'nb-root';

      root.innerHTML = `
<button id="nb-btn" aria-label="Åpne chat"><span class="nb-open">💬</span><span class="nb-close">✕</span></button>
<div id="nb-win">
  <div id="nb-hdr"><h3>${this.esc(this.config.name)}</h3><button aria-label="Lukk" id="nb-close-btn">✕</button></div>
  <div id="nb-msgs"></div>
  <div id="nb-input"><input type="text" placeholder="Skriv ditt spørsmål..." aria-label="Melding"><button>Send</button></div>
  <div id="nb-pwr"><a href="https://norskbot.no" target="_blank" rel="noopener">Powered by NorskBot</a></div>
</div>`;

      document.body.appendChild(root);

      this.els.root = root;
      this.els.btn = root.querySelector('#nb-btn');
      this.els.win = root.querySelector('#nb-win');
      this.els.msgs = root.querySelector('#nb-msgs');
      this.els.input = root.querySelector('#nb-input input');
      this.els.send = root.querySelector('#nb-input button');
      this.els.closeBtn = root.querySelector('#nb-close-btn');

      // Welcome message
      this.addMsg('a', this.config.welcome_message);
    }

    bindEvents() {
      this.els.btn.onclick = () => this.toggle();
      this.els.closeBtn.onclick = () => this.toggle();
      this.els.send.onclick = () => this.send();
      this.els.input.onkeypress = (e) => { if (e.key === 'Enter') this.send(); };
      document.addEventListener('keydown', (e) => {
        if ((e.metaKey || e.ctrlKey) && e.key === 'i') { e.preventDefault(); this.toggle(); }
      });
    }

    toggle() {
      this.isOpen = !this.isOpen;
      this.els.win.classList.toggle('nb-show', this.isOpen);
      this.els.btn.classList.toggle('nb-open', this.isOpen);
      if (this.isOpen) this.els.input.focus();
    }

    async send() {
      const text = this.els.input.value.trim();
      if (!text) return;

      this.addMsg('u', text);
      this.els.input.value = '';
      this.els.send.disabled = true;

      // Show typing indicator
      const typing = this.showTyping();

      try {
        const r = await fetch(this.apiUrl + '/v1/chat/message', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json', 'X-Site-Id': this.siteId },
          body: JSON.stringify({ message: text, sessionId: this.sessionId }),
        });

        typing.remove();

        if (!r.ok) throw new Error('API ' + r.status);
        const d = await r.json();
        this.addMsg('a', d.message, d.sources);
      } catch (e) {
        typing.remove();
        console.error('NorskBot:', e);
        this.addMsg('a', 'Beklager, noe gikk galt. Prøv igjen eller kontakt oss direkte.');
      } finally {
        this.els.send.disabled = false;
        this.els.input.focus();
      }
    }

    showTyping() {
      const el = document.createElement('div');
      el.className = 'nb-msg nb-msg-a';
      el.innerHTML = '<div class="nb-typing"><span></span><span></span><span></span></div>';
      this.els.msgs.appendChild(el);
      this.els.msgs.scrollTop = this.els.msgs.scrollHeight;
      return el;
    }

    addMsg(role, content, sources) {
      const el = document.createElement('div');
      el.className = 'nb-msg nb-msg-' + role;
      let h = '<div class="nb-msg-t">' + this.esc(content) + '</div>';
      if (sources && sources.length) {
        h += '<div class="nb-src">';
        for (const s of sources) {
          if (s.url) h += '<a href="' + this.esc(s.url) + '" target="_blank" rel="noopener">' + this.esc(s.title || 'Kilde') + '</a>';
        }
        h += '</div>';
      }
      el.innerHTML = h;
      this.els.msgs.appendChild(el);
      this.els.msgs.scrollTop = this.els.msgs.scrollHeight;
    }

    esc(t) {
      const m = {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'};
      return String(t).replace(/[&<>"']/g, c => m[c]);
    }
  }

  function boot() {
    const scripts = document.querySelectorAll('script[data-site],script[data-site-id]');
    let script = null;
    for (const s of scripts) {
      if (s.src && s.src.includes('widget')) { script = s; break; }
    }
    if (!script) script = document.currentScript;

    const siteId = script?.getAttribute('data-site') || script?.getAttribute('data-site-id');
    const apiUrl = script?.getAttribute('data-api-url') || window.location.origin;
    const color = script?.getAttribute('data-color');
    const position = script?.getAttribute('data-position');

    if (!siteId) { console.error('NorskBot: Missing data-site attribute'); return; }

    const w = new ChatWidget({ siteId, apiUrl, color: color || undefined, position: position || undefined });
    if (color) w._userColor = true;
    if (position) w._userPosition = true;
    w.init();
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', boot);
  } else {
    boot();
  }

  window.NorskChatbot = ChatWidget;
})();
